#!/usr/bin/env python3
"""Git repos for MenuSprite: branch, uncommitted changes and unpushed commits of the folders in repos.txt, as
board blocks. The face's value runs this same command (same every and timeout), so one scan feeds both: the
value reads the first tile's figure (path 0.row.0.value) and the board draws the blocks."""
import json
import os
import shlex
import subprocess
from concurrent.futures import ThreadPoolExecutor

HERE = os.path.dirname(os.path.abspath(__file__))
SHOWN = 12
LIMIT = 200  # repositories scanned; more are named in a note rather than slowing every scan


def folders():
    """Each line of repos.txt is a repository, or a folder whose subfolders are repositories."""
    found = []
    with open(os.path.join(HERE, "repos.txt")) as listing:
        for line in listing:
            line = line.strip()
            if not line or line.startswith("#"):
                continue
            path = os.path.expanduser(line)
            # .git is a folder in a clone and a file in a worktree.
            if os.path.exists(os.path.join(path, ".git")):
                found.append(path)
            elif os.path.isdir(path):
                found += sorted(os.path.join(path, name) for name in os.listdir(path)
                                if os.path.exists(os.path.join(path, name, ".git")))
    return found


def status(path):
    # --no-optional-locks: never hold the index lock while the user runs git in the same repo.
    done = subprocess.run(["git", "--no-optional-locks", "-C", path, "status", "--porcelain=v2", "--branch"],
                          capture_output=True, text=True, timeout=10)
    branch, ahead, behind, changes = "?", 0, 0, 0
    if done.returncode != 0:
        # A repository git cannot read must not pass for a clean one.
        problem = (done.stderr.strip().splitlines() or ["git status failed"])[-1]
        return {"name": os.path.basename(path), "path": path, "branch": problem, "ahead": 0, "behind": 0, "changes": 0, "failed": True}
    for line in done.stdout.splitlines():
        if line.startswith("# branch.head "):
            branch = line.split(" ", 2)[2]
        elif line.startswith("# branch.ab "):
            ahead, behind = (abs(int(n)) for n in line.split(" ")[2:4])
        elif not line.startswith("#"):
            changes += 1
    return {"name": os.path.basename(path), "path": path, "branch": branch, "ahead": ahead, "behind": behind, "changes": changes, "failed": False}


def plain(text):
    # Board text reads {word} as one of the sprite's values; a folder or branch name never means one.
    return text.replace("{", "{\u200b")


def row(repo):
    counts = "git failed" if repo["failed"] else " · ".join(part for part in ("%d changed" % repo["changes"] if repo["changes"] else "",
                                          "%d to push" % repo["ahead"] if repo["ahead"] else "",
                                          "%d to pull" % repo["behind"] if repo["behind"] else "") if part)
    return {"row": [
        {"stack": [{"text": plain(repo["name"]), "lines": 1, "truncate": "middle"},
                   {"text": plain(repo["branch"]), "font": "caption", "color": "gray", "lines": 1}], "spacing": 1},
        {"text": counts, "font": "caption", "color": "red" if repo["failed"] else "orange" if repo["changes"] else "blue", "fit": True},
    ], "run": "open -a Terminal " + shlex.quote(repo["path"])}  # a click opens the repository in Terminal


with ThreadPoolExecutor(8) as pool:
    found = folders()
    repos = list(pool.map(status, found[:LIMIT]))
repos.sort(key=lambda r: (not r["changes"], not r["ahead"], r["name"].lower()))
busy = [repo for repo in repos if repo["failed"] or repo["changes"] or repo["ahead"]]
blocks = [{"row": [{"value": sum(1 for repo in repos if repo["changes"]), "caption": "Uncommitted"},
                   {"value": sum(1 for repo in repos if repo["ahead"]), "caption": "To push"},
                   {"value": len(repos) - len(busy), "caption": "Clean"}]}]
if not repos:
    blocks.append({"text": "No repositories found. Add folders to repos.txt (Edit list).", "font": "caption", "color": "gray"})
elif busy:
    rows = [row(repo) for repo in busy[:SHOWN]]
    if len(busy) > SHOWN:
        rows.append({"text": "and %d more" % (len(busy) - SHOWN), "font": "caption", "color": "gray"})
    blocks.append({"card": rows, "title": "Needs attention"})
else:
    blocks.append({"text": "Everything is committed and pushed.", "icon": "checkmark.circle", "color": "gray"})
if len(found) > LIMIT:
    blocks.append({"text": "Scanned the first %d of %d repositories." % (LIMIT, len(found)), "font": "caption", "color": "gray"})
print(json.dumps(blocks))
